-- CRM Analysis Dataset SQL Export
-- Generated from CRM_ANALYSIS_DATASET.xlsx
create database CRM;

DROP TABLE IF EXISTS `dim_account`;
CREATE TABLE `dim_account` (
  `account_id` VARCHAR(50),
  `account_name` VARCHAR(94),
  `industry` VARCHAR(50),
  `region` DECIMAL(18,4),
  `annual_revenue` DECIMAL(18,4),
  `account_type` VARCHAR(50),
  `billing_country` VARCHAR(50),
  `owner_id` VARCHAR(50)
);
 
 SELECT * FROM dim_account;
 
 DROP TABLE IF EXISTS `dim_user`;
CREATE TABLE `dim_user` (
  `user_id` VARCHAR(50),
  `full_name` VARCHAR(50),
  `role_id` VARCHAR(50),
  `department` VARCHAR(50),
  `is_active` VARCHAR(50),
  `manager_id` VARCHAR(50)
);


 SELECT * FROM dim_user;

DROP TABLE IF EXISTS `fact_opp`;
CREATE TABLE `fact_opp` (
  `opportunity_id` VARCHAR(50),
  `account_id` VARCHAR(50),
  `owner_id` VARCHAR(50),
  `industry` VARCHAR(50),
  `stage` VARCHAR(50),
  `stage_group` VARCHAR(50),
  `amount` DECIMAL(18,4),
  `expected_amount` DECIMAL(18,4),
  `close_date` DATETIME,
  `created_date` DATETIME,
  `days_to_close` BIGINT,
  `is_won` VARCHAR(50),
  `is_closed` VARCHAR(50),
  `closed_lost_reason` VARCHAR(50),
  `deal_size_band` VARCHAR(50),
  `fiscal_year` BIGINT,
  `fiscal_quarter` BIGINT,
  `probability_pct` DECIMAL(18,4),
  `opportunity_type` VARCHAR(50)
);



DROP TABLE IF EXISTS `fact_opp_product`;
CREATE TABLE `fact_opp_product` (
  `line_item_id` VARCHAR(50),
  `opportunity_id` VARCHAR(50),
  `product_name` VARCHAR(50),
  `product_code` VARCHAR(50),
  `quantity` DECIMAL(18,4),
  `list_price` DECIMAL(18,4),
  `sales_price` DECIMAL(18,4),
  `discount` DECIMAL(18,4),
  `total_price` DECIMAL(18,4)
);




DROP TABLE IF EXISTS `fact_lead`;
CREATE TABLE `fact_lead` (
  `lead_id` VARCHAR(50),
  `conv_account_id` VARCHAR(50),
  `conv_opp_id` VARCHAR(50),
  `lead_source` VARCHAR(50),
  `status` VARCHAR(50),
  `industry` VARCHAR(50),
  `is_converted` VARCHAR(50),
  `lead_score` DECIMAL(18,4),
  `created_date` DATETIME,
  `age_days` BIGINT,
  `conv_expected_amount` DECIMAL(18,4),
  `conv_stage` VARCHAR(50)
);


SELECT COUNT(*) FROM dim_account;

SELECT COUNT(*) FROM dim_user;

SELECT COUNT(*) FROM fact_lead;

SELECT COUNT(*) FROM fact_opp;

SELECT COUNT(*) FROM fact_opp_product;

#Opportunity + Account + User
SELECT
    o.opportunity_id,
    o.account_id,
    a.account_name,
    a.industry,
    o.stage,
    o.amount,
    o.expected_amount,
    o.close_date,
    o.is_won,
    u.full_name AS opportunity_owner,
    u.department
FROM fact_opp o
LEFT JOIN dim_account a
    ON o.account_id = a.account_id
LEFT JOIN dim_user u
    ON o.owner_id = u.user_id;


#2. Opportunity + Products

SELECT
    o.opportunity_id,
    a.account_name,
    o.stage,
    o.amount,
    p.product_name,
    p.product_code,
    p.quantity,
    p.sales_price,
    p.discount,
    p.total_price
FROM fact_opp o
LEFT JOIN dim_account a
    ON o.account_id = a.account_id
LEFT JOIN fact_opp_product p
    ON o.opportunity_id = p.opportunity_id;
    
    #Lead + Converted Account + Opportunity
    
    SELECT
    l.lead_id,
    l.lead_source,
    l.status,
    l.industry,
    l.is_converted,
    l.lead_score,
    l.created_date,
    a.account_name,
    a.account_type,
    o.opportunity_id,
    o.stage,
    o.amount,
    o.expected_amount
FROM fact_lead l
LEFT JOIN dim_account a
    ON l.conv_account_id = a.account_id
LEFT JOIN fact_opp o
    ON l.conv_opp_id = o.opportunity_id;
    
    #Complete CRM Join
    
    SELECT
    l.lead_id,
    l.lead_source,
    l.status AS lead_status,
    l.industry AS lead_industry,
    l.is_converted,
    l.lead_score,
    
    a.account_id,
    a.account_name,
    a.industry AS account_industry,
    a.account_type,
    a.billing_country,
    
    o.opportunity_id,
    o.stage,
    o.stage_group,
    o.amount,
    o.expected_amount,
    o.close_date,
    o.is_won,
    o.is_closed,
    o.deal_size_band,
    
    u.user_id,
    u.full_name AS owner_name,
    u.department,
    
    p.product_name,
    p.product_code,
    p.quantity,
    p.sales_price,
    p.discount,
    p.total_price

FROM fact_lead l

LEFT JOIN dim_account a
    ON l.conv_account_id = a.account_id

LEFT JOIN fact_opp o
    ON l.conv_opp_id = o.opportunity_id

LEFT JOIN dim_user u
    ON o.owner_id = u.user_id

LEFT JOIN fact_opp_product p
    ON o.opportunity_id = p.opportunity_id;
    
    #Revenue by Account
    SELECT
    a.account_name,
    a.industry,
    COUNT(o.opportunity_id) AS total_opportunities,
    SUM(o.amount) AS total_revenue,
    SUM(o.expected_amount) AS expected_revenue
FROM dim_account a
LEFT JOIN fact_opp o
    ON a.account_id = o.account_id
GROUP BY
    a.account_name,
    a.industry
ORDER BY total_revenue DESC;

#Opportunity Performance by Salesperson
SELECT
    u.full_name AS sales_owner,
    COUNT(o.opportunity_id) AS total_opportunities,
    SUM(o.amount) AS total_amount,
    SUM(
        CASE
            WHEN o.is_won = '1' THEN o.amount
            ELSE 0
        END
    ) AS won_revenue
FROM dim_user u
LEFT JOIN fact_opp o
    ON u.user_id = o.owner_id
GROUP BY u.full_name
ORDER BY won_revenue DESC;
    
    #Product Revenue
    
    SELECT
    p.product_name,
    SUM(p.quantity) AS total_quantity,
    SUM(p.total_price) AS total_revenue,
    AVG(p.sales_price) AS avg_sales_price
FROM fact_opp_product p
GROUP BY p.product_name
ORDER BY total_revenue DESC;



#CRM Opportunity Dashboard
# Total Opportunities
SELECT COUNT(*) AS Total_Opportunities
FROM Fact_opp;

#Total Opportunity Amount
SELECT SUM(amount) AS Total_Opportunity_Amount
FROM Fact_opp;

#Won Opportunities
SELECT COUNT(*) AS Won_Opportunities
FROM Fact_opp
WHERE stage = 'Closed Won';

#Lost Opportunities
SELECT COUNT(*) AS Lost_Opportunities
FROM Fact_opp
WHERE stage = 'Closed Lost';

#Win Rate %
SELECT 
    ROUND(
        SUM(CASE WHEN stage = 'Closed Won' THEN 1 ELSE 0 END) * 100.0 /
        NULLIF(SUM(CASE WHEN stage IN ('Closed Won','Closed Lost') THEN 1 ELSE 0 END), 0),
        2
    ) AS Win_Rate_Percent
FROM Fact_opp;

#Average Opportunity Amount
SELECT ROUND(AVG(amount), 2) AS Average_Opportunity_Amount
FROM Fact_opp;

#CRM Lead Dashboard
#Total Leads
SELECT COUNT(lead_id) AS Total_Leads
FROM Fact_lead;

#Lost Leads
SELECT COUNT(lead_id) AS Lost_Leads
FROM Fact_lead
WHERE status = 'Lost';

#Average Lead Score
SELECT 
    ROUND(AVG(lead_score), 2) AS Average_Lead_Score
FROM fact_lead
WHERE lead_score IS NOT NULL;


#Lead Dashboard View
CREATE  VIEW vw_lead_dashboard AS
SELECT
    l.lead_id,
    l.lead_source,
    l.status AS lead_status,
    l.industry,
    l.is_converted,
    l.lead_score,
    l.created_date,
    l.age_days,
    l.conv_expected_amount,
    l.conv_stage,

    a.account_id,
    a.account_name,
    a.account_type,
    a.region,
    a.annual_revenue,
    a.billing_country,

    o.opportunity_id,
    o.stage AS opportunity_stage,
    o.amount AS opportunity_amount,
    o.expected_amount AS opportunity_expected_amount,
    o.is_won,
    o.is_closed

FROM Fact_lead l

LEFT JOIN dim_account a
    ON l.conv_account_id = a.account_id

LEFT JOIN Fact_opp o
    ON l.conv_opp_id = o.opportunity_id;
    
    
    SELECT *
FROM vw_lead_dashboard;


#Lead KPI View
CREATE OR REPLACE VIEW vw_lead_kpi AS
SELECT
    COUNT(lead_id) AS total_leads,

    SUM(
        CASE 
            WHEN is_converted = 1 THEN 1
            ELSE 0
        END
    ) AS converted_leads,

    SUM(
        CASE 
            WHEN is_converted = 0 THEN 1
            ELSE 0
        END
    ) AS not_converted_leads,

    ROUND(
        100.0 *
        SUM(CASE WHEN is_converted = 1 THEN 1 ELSE 0 END)
        / NULLIF(COUNT(lead_id), 0),
        2
    ) AS conversion_rate,

    ROUND(
        SUM(
            CASE
                WHEN is_converted = 1
                THEN COALESCE(conv_expected_amount, 0)
                ELSE 0
            END
        ),
        2
    ) AS converted_expected_revenue,

    ROUND(AVG(lead_score), 2) AS average_lead_score

FROM Fact_lead;

SELECT *
FROM vw_lead_kpi;

#Lead Status View
CREATE OR REPLACE VIEW vw_lead_status AS
SELECT
    status AS lead_status,
    COUNT(lead_id) AS total_leads
FROM Fact_lead
GROUP BY status;

#Lead Industry View
CREATE OR REPLACE VIEW vw_lead_industry AS
SELECT
    industry,
    COUNT(lead_id) AS total_leads,
    SUM(CASE WHEN is_converted = 1 THEN 1 ELSE 0 END) AS converted_leads,
    ROUND(AVG(lead_score), 2) AS average_lead_score
FROM Fact_lead
GROUP BY industry
ORDER BY total_leads DESC;

#Opportunity Dashboard View
CREATE OR REPLACE VIEW vw_opportunity_dashboard AS
SELECT
    o.opportunity_id,
    o.account_id,
    o.owner_id,

    o.industry,
    o.stage,
    o.stage_group,
    o.amount,
    o.expected_amount,
    o.close_date,
    o.created_date,
    o.days_to_close,

    o.is_won,
    o.is_closed,
    o.closed_lost_reason,
    o.deal_size_band,

    o.fiscal_year,
    o.fiscal_quarter,
    o.probability_pct,
    o.opportunity_type,

    a.account_name,
    a.account_type,
    a.region,
    a.annual_revenue,
    a.billing_country,

    u.full_name AS owner_name,
    u.department,
    u.role_id

FROM Fact_opp o

LEFT JOIN dim_account a
    ON o.account_id = a.account_id

LEFT JOIN dim_user u
    ON o.owner_id = u.user_id;
    
    SELECT *
FROM vw_opportunity_dashboard;

#Opportunity KPI View
#For your KPI cards:
#Total Opportunities
#Active/Open Opportunities
#Won Revenue
#Win Rate

CREATE OR REPLACE VIEW vw_opportunity_kpi AS
SELECT

    COUNT(opportunity_id) AS total_opportunities,

    SUM(
        CASE
            WHEN is_closed = 0 THEN 1
            ELSE 0
        END
    ) AS active_opportunities,

    SUM(
        CASE
            WHEN is_won = 1 THEN amount
            ELSE 0
        END
    ) AS total_won_revenue,

    ROUND(
        100.0 *
        SUM(CASE WHEN is_won = 1 THEN 1 ELSE 0 END)
        / NULLIF(
            SUM(CASE WHEN is_closed = 1 THEN 1 ELSE 0 END),
            0
        ),
        2
    ) AS win_rate,

    SUM(amount) AS total_pipeline,

    SUM(expected_amount) AS total_expected_revenue

FROM Fact_opp;


SELECT *
FROM vw_opportunity_kpi;


#Opportunity Stage View
CREATE OR REPLACE VIEW vw_opportunity_stage AS
SELECT
    stage,
    COUNT(opportunity_id) AS total_opportunities,
    SUM(amount) AS total_amount,
    SUM(expected_amount) AS expected_revenue
FROM Fact_opp
GROUP BY stage
ORDER BY total_opportunities DESC;

#Opportunity Industry View
CREATE OR REPLACE VIEW vw_opportunity_industry AS
SELECT
    industry,
    COUNT(opportunity_id) AS total_opportunities,
    SUM(amount) AS total_amount,
    SUM(
        CASE
            WHEN is_won = 1 THEN amount
            ELSE 0
        END
    ) AS won_revenue
FROM Fact_opp
GROUP BY industry
ORDER BY total_amount DESC;


#Top 10 Accounts by Won Revenue
CREATE OR REPLACE VIEW vw_top10_accounts_won AS
SELECT
    a.account_id,
    a.account_name,
    a.industry,
    a.region,

    SUM(o.amount) AS won_revenue,

    COUNT(o.opportunity_id) AS won_opportunities

FROM Fact_opp o

INNER JOIN dim_account a
    ON o.account_id = a.account_id

WHERE o.is_won = 1

GROUP BY
    a.account_id,
    a.account_name,
    a.industry,
    a.region

ORDER BY won_revenue DESC

LIMIT 10;